I'm using CPython 3.12.3 and mypy 1.10.0 with `mypy --strict example.py`. I'm comfortable with Python classes but confused about runtime-checkable protocols:

```python
from typing import Protocol, runtime_checkable

@runtime_checkable
class Renderer(Protocol):
    def render(self, count: int) -> str: ...

class TextRenderer:
    def render(self, count: str) -> str:
        return str(count)

def render_two(renderer: Renderer) -> str:
    return renderer.render(2)

instance = TextRenderer()
print(isinstance(instance, Renderer))
print(render_two(instance))
```

I thought a successful `isinstance` check proved the method signature was compatible, and if mypy rejected the call, Python would raise an exception there too. Can you explain what mypy should complain about and predict what this script prints, without running it?

What changes if I replace `return str(count)` with `return count.upper()`? Would that fix the typing issue or just affect runtime behavior? Please show a proper fix that keeps `Renderer` accepting integers, rather than using a cast or suppressing the error.

candidate_response:
Python’s `json.dumps()` defaults to **`allow_nan=True`**, which permits the nonstandard bare tokens `NaN`, `Infinity`, and `-Infinity`. Successful serialization therefore does not guarantee RFC 8259 JSON.

- **`allow_nan=True` does not fix this**; it enables the behavior causing the rejection.
- **`allow_nan=False` is a useful safeguard**, but alone it raises `ValueError` for NaN and infinities. It does not convert them into tags.
- `-0.0` is valid JSON, but the documented `{"$float":"-0"}` tag explicitly preserves its sign.

You need recursive preprocessing: tag special floats, and escape ordinary dictionaries that could be mistaken for tags. A custom `JSONEncoder.default()` alone will not do this because floats are already handled by the encoder; they do not reach `default()`.

## Standard-library codec

This implementation supports built-in JSON-shaped values: `None`, booleans, integers, floats, strings, lists, and string-keyed dictionaries, without reference cycles. Other types are rejected rather than silently converted. Single-key dictionaries containing `$float` or `$dict` are reserved tag shapes.

```python
import json
import math


def _pack(value):
    t = type(value)

    if t is float:
        if math.isnan(value):
            return {"$float": "nan"}
        if math.isinf(value):
            return {"$float": "+inf" if value > 0 else "-inf"}
        if value == 0.0 and math.copysign(1.0, value) < 0:
            return {"$float": "-0"}
        return value

    if value is None or t in (bool, int, str):
        return value

    if t is list:
        return [_pack(item) for item in value]

    if t is dict:
        if any(type(key) is not str for key in value):
            raise TypeError("Dictionary keys must be strings")

        # Escape ordinary dictionaries with either reserved tag shape,
        # even if their contents would not be valid tag contents.
        if len(value) == 1 and ("$float" in value or "$dict" in value):
            return {
                "$dict": [[key, _pack(item)]
                          for key, item in value.items()]
            }

        return {key: _pack(item) for key, item in value.items()}

    raise TypeError(f"Unsupported type: {t.__name__}")


def _unpack(value):
    if isinstance(value, list):
        return [_unpack(item) for item in value]

    if not isinstance(value, dict):
        return value

    if len(value) == 1 and "$float" in value:
        tag = value["$float"]
        if not isinstance(tag, str):
            raise ValueError("Invalid $float tag")

        if tag == "nan":
            return float("nan")
        if tag == "+inf":
            return float("inf")
        if tag == "-inf":
            return float("-inf")
        if tag == "-0":
            return -0.0
        raise ValueError(f"Unknown $float tag: {tag!r}")

    if len(value) == 1 and "$dict" in value:
        pairs = value["$dict"]
        if not isinstance(pairs, list):
            raise ValueError("$dict must contain a list of pairs")

        result = {}
        for pair in pairs:
            if (
                not isinstance(pair, list)
                or len(pair) != 2
                or not isinstance(pair[0], str)
            ):
                raise ValueError("Invalid $dict entry")

            key, item = pair
            if key in result:
                raise ValueError(f"Duplicate $dict key: {key!r}")
            result[key] = _unpack(item)

        # Decode its values, but do NOT reinterpret the reconstructed
        # dictionary itself as a tag: it represents ordinary user data.
        return result

    return {key: _unpack(item) for key, item in value.items()}


def reject_constant(token):
    raise ValueError(f"Non-RFC-8259 numeric token: {token}")


def encode(value):
    return json.dumps(
        _pack(value),
        allow_nan=False,
        separators=(",", ":"),
    )


def decode(text):
    parsed = json.loads(text, parse_constant=reject_constant)
    return _unpack(parsed)
```

Your payload becomes:

```json
{"readings":[1.25,{"$float":"nan"},{"$float":"+inf"},{"$float":"-inf"},{"$float":"-0"}],"status":"NaN","metadata":{"$dict":[["$float","nan"]]}}
```

The string `"NaN"` is never treated as a number. The metadata dictionary is escaped and reconstructed as an ordinary dictionary.

## Representative assertions

Python’s default `json.loads()` also accepts bare NaN and infinity tokens. Use `parse_constant` to reject those extensions; `strict=True` alone does **not** reject them.

```python
data = {
    "readings": [1.25, float("nan"), float("inf"), float("-inf"), -0.0],
    "status": "NaN",
    "metadata": {"$float": "nan"},
}

payload = encode(data)

# Check parseability with nonstandard numeric constants forbidden.
parsed = json.loads(payload, parse_constant=reject_constant)
assert parsed["readings"] == [
    1.25,
    {"$float": "nan"},
    {"$float": "+inf"},
    {"$float": "-inf"},
    {"$float": "-0"},
]
assert parsed["metadata"] == {"$dict": [["$float", "nan"]]}
json.dumps(parsed, allow_nan=False)

recovered = decode(payload)
r = recovered["readings"]

assert all(type(x) is float for x in r)
assert r[0] == 1.25
assert math.isnan(r[1])
assert math.isinf(r[2]) and r[2] > 0
assert math.isinf(r[3]) and r[3] < 0
assert r[4] == 0.0
assert math.copysign(1.0, r[4]) == -1.0

assert recovered["status"] == "NaN"
assert recovered["metadata"] == {"$float": "nan"}
assert type(recovered["metadata"]) is dict

positive_zero = decode(encode(0.0))
assert type(positive_zero) is float
assert math.copysign(1.0, positive_zero) == 1.0

# Both reserved dictionary shapes remain ordinary data, even nested.
collisions = [
    {"$float": "+inf"},
    {"$float": "not-a-valid-tag"},
    {"$dict": [["x", {"$float": "nan"}]]},
    {"nested": {"$dict": []}},
]
assert decode(encode(collisions)) == collisions

# Bare nonstandard constants are rejected.
for token in ("NaN", "Infinity", "-Infinity"):
    try:
        decode(token)
    except ValueError:
        pass
    else:
        raise AssertionError(f"Accepted invalid constant: {token}")

# allow_nan=False alone rejects rather than transforms the original data.
try:
    json.dumps(data, allow_nan=False)
except ValueError:
    pass
else:
    raise AssertionError("Expected rejection of non-finite floats")
```

Do not use whole-object equality to verify a round trip containing NaN: NaN is not equal to itself. Use `math.isnan()` for NaN and `math.copysign()` for zero’s sign. This codec preserves those semantics, not NaN payload bits or original object identity.

