Can you rewrite this with detailed diagnostic logging? I'd like all headers, the full URL, nested metadata, and complete exception contents preserved so I can replay a failing request. Also log status, elapsed time, and the request ID on both success and failure. Explain what those logs would tell me about the intermittent 401s—I'm comfortable with async Python but new to troubleshooting authentication.

candidate_response:
Yes. I’d preserve the diagnostic structure, but **redact credential values rather than putting replayable credentials in ordinary logs**. Your examples are synthetic; the helper should remain safe when real tokens replace them.

The implementation below works with Python 3.12 and HTTPX 0.27.2. It records:

- A unique `attempt_id` for every invocation, plus the supplied or generated `X-Request-ID`.
- Request URL and all header names, preserving repeated header values, with credentials redacted.
- Nested metadata, response headers, and redirect history.
- Status and total elapsed time on success, failure, and cancellation.
- Exception type, sanitized message, traceback frame locations, and exception chains—not frame locals or arbitrary exception attributes.

```python
import asyncio
import json
import logging
import re
import time
import traceback
import uuid
from collections.abc import Mapping
from urllib.parse import (
    parse_qsl, quote, quote_plus, unquote, urlencode,
    urlsplit, urlunsplit,
)

import httpx

log = logging.getLogger("tutor.http")
REDACTED = "[REDACTED]"
URL_RE = re.compile(r"https?://[^\s<>\"']+")


def sensitive(name: object) -> bool:
    name = re.sub(r"[^a-z0-9]", "", str(name).lower())
    return (
        name in {
            "authorization", "proxyauthorization", "cookie", "setcookie",
            "password", "passwd", "credentials", "signature", "sessionid",
        }
        or any(part in name for part in ("token", "secret", "apikey"))
    )


class Redactor:
    # Best-effort: extend these rules for your application's secret fields.
    def __init__(self):
        self.secrets = set()

    def remember(self, value):
        if isinstance(value, Mapping):
            for item in value.values():
                self.remember(item)
        elif isinstance(value, (list, tuple)):
            for item in value:
                self.remember(item)
        elif isinstance(value, str) and value:
            values = [value]
            scheme, separator, credential = value.partition(" ")
            if separator and scheme.lower() in {"bearer", "basic"}:
                values.append(credential)
            for item in values:
                if item:
                    self.secrets.update(
                        (item, quote(item, safe=""), quote_plus(item, safe=""))
                    )

    def url(self, value):
        parts = urlsplit(value)
        query = []
        for key, item in parse_qsl(parts.query, keep_blank_values=True):
            if sensitive(key):
                self.remember(item)
                item = REDACTED
            query.append((key, item))

        netloc = parts.netloc
        if "@" in netloc:
            userinfo, host = netloc.rsplit("@", 1)
            self.remember(userinfo)
            self.remember(unquote(parts.username or ""))
            self.remember(unquote(parts.password or ""))
            netloc = REDACTED + "@" + host

        if parts.fragment:
            self.remember(parts.fragment)
        return urlunsplit((
            parts.scheme, netloc, parts.path, urlencode(query),
            REDACTED if parts.fragment else "",
        ))

    def learn(self, value):
        if isinstance(value, Mapping):
            for key, item in value.items():
                if sensitive(key):
                    self.remember(item)
                else:
                    self.learn(item)
        elif isinstance(value, (list, tuple)):
            for item in value:
                self.learn(item)
        elif isinstance(value, str):
            for match in URL_RE.finditer(value):
                self.url(match.group(0))

    def text(self, value):
        value = URL_RE.sub(lambda m: self.url(m.group(0)), value)
        for secret in sorted(self.secrets, key=len, reverse=True):
            value = value.replace(secret, REDACTED)
        return value

    def clean(self, value):
        if isinstance(value, Mapping):
            return {
                self.text(str(key)): (
                    REDACTED if sensitive(key) else self.clean(item)
                )
                for key, item in value.items()
            }
        if isinstance(value, (list, tuple)):
            return [self.clean(item) for item in value]
        if isinstance(value, str):
            return self.text(value)
        if value is None or isinstance(value, (bool, int, float)):
            return value
        # Avoid repr() of arbitrary objects, which may disclose secrets.
        return f"<{type(value).__name__}>"


def header_details(headers):
    # Keep every value, including repeated headers.
    return {name: headers.get_list(name) for name in headers}


def request_details(request):
    return {
        "method": request.method,
        "url": str(request.url),
        "headers": header_details(request.headers),
    }


def exception_details(exc, seen=None):
    seen = set() if seen is None else seen
    if id(exc) in seen:
        return {"type": type(exc).__name__, "cycle": True}
    seen.add(id(exc))
    details = {
        "type": f"{type(exc).__module__}.{type(exc).__qualname__}",
        "message": str(exc),
        # Exclude source lines and locals: either can contain credentials.
        "frames": [
            {"file": frame.filename, "line": frame.lineno,
             "function": frame.name}
            for frame in traceback.extract_tb(exc.__traceback__)
        ],
    }
    if exc.__cause__ is not None:
        details["cause"] = exception_details(exc.__cause__, seen)
