def sliding_windows(items, size):
    """The outer function validates immediately; the nested generator consumes lazily."""
    if isinstance(size, bool) or not isinstance(size, int):
        raise TypeError("size must be an integer, not bool")
    if size < 1:
        raise ValueError("size must be at least 1")

    def generate():
        iterator = iter(items)
        window = []
        for _ in range(size):
            try:
                window.append(next(iterator))
            except StopIteration:
                return

        yield tuple(window)
        for item in iterator:
            del window[0]
            window.append(item)
            yield tuple(window)

    return generate()

"""Read strictly validated CSV score records while preserving names."""

import csv
import io


def _validate_quoting(text):
    """Reject misplaced quotes, unterminated quotes, and closing-quote junk."""
    state = "start"

    for character in text:
        if state == "quoted":
            if character == '"':
                state = "closed"
        elif state == "closed":
            if character == '"':
                state = "quoted"
            elif character in ",\r\n":
                state = "start"
            else:
                raise ValueError("Unexpected character after a closing quote")
        elif state == "start":
            if character == '"':
                state = "quoted"
            elif character not in ",\r\n":
                state = "unquoted"
        else:
            if character == '"':
                raise ValueError("Quote inside an unquoted field")
            if character in ",\r\n":
                state = "start"

    if state == "quoted":
        raise ValueError("Unterminated quoted field")


def _parse_score(text):
    """Validate an ASCII integer and convert it without string-length limits."""
    negative = text.startswith("-")
    digits = text[1:] if text.startswith(("+", "-")) else text

    if not digits or any(character < "0" or character > "9" for character in digits):
        raise ValueError("Scores must be signed or unsigned ASCII integers")

    value = 0
    for offset in range(0, len(digits), 9):
        chunk = digits[offset:offset + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return -value if negative else value


def read_scores(text):
    """Return ordered (name, integer_score) tuples from CSV text.

    Require the literal header name,score, followed by LF, CRLF, or EOF.
    Every data record must contain a nonempty name and an ASCII integer.
    Preserve names verbatim and retain duplicates in their original order.
    Invalid input raises ValueError; partial results are never returned.
    """
    if not isinstance(text, str):
        raise ValueError("CSV input must be text")

    if not (
        text == "name,score"
        or text.startswith("name,score\n")
        or text.startswith("name,score\r\n")
    ):
        raise ValueError("Header must be exactly name,score")

    _validate_quoting(text)
    previous_limit = csv.field_size_limit()
    results = []

    try:
        csv.field_size_limit(max(previous_limit, len(text)))
        with io.StringIO(text, newline="") as stream:
            reader = csv.reader(stream, strict=True)
            if next(reader, None) != ["name", "score"]:
                raise ValueError("Header must be exactly name,score")

            for record in reader:
                if len(record) != 2:
